#!/usr/bin/env bash

#PPA.cen.unit.fa contains the global consensus sequences of SAT113 and SAT483 generated by the SAT_array_pipeline_v2.sh pipeline.
genome=path/PPA.final.genome.fna
centromere_bed=PPA.centromere.region.slop.500K.bed
centromere_unit_seq=PPA.cen.unit.fa
prefix=PPA

bedtools getfasta -fi $genome -bed $centromere_bed -fo ${prefix}.centromere.fasta
seqkit split -i ${prefix}.centromere.fasta
for i in ${prefix}.centromere.fasta.split/*.fasta; do root=`basename $i .fasta`; echo "python path/HiCAT/HiCAT.py -th 5 -i $i -t $centromere_unit_seq -o $root";done > para.HiCAT.sh
ParaFly -c para.HiCAT.sh -CPU 10

#SAT113 HOR
#PPA.SAT113.consensus.fa contains the global consensus sequence of SAT113 generated by the SAT_array_pipeline_v2.sh pipeline.
python path/HiCAT/HiCAT.py \
  -i PPA.centromere.fasta.split/PPA.centromere.part_ChrC1__112292614-114092614.fasta \
  -t PPA.SAT113.consensus.fa \
  -o PPA.centromere.part_ChrC1__112292614-114092614_SAT113 \
  -ms 0.80 \
  -st 0.01 \
  -mh 120 \
  -sn 2 \
  -sp 20 \
  -th 8
